(function(root){
 'use strict';
 const C=root.SiaPlayCore,$=s=>document.querySelector(s),E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const KEY='my-sia-play-v1',ART='assets/play/',PROPS=['apple','banana','berry','orange','dog','cat','rabbit','chick','frog','turtle','butterfly','tree','sun','moon','star','rocket','bus','book','bowl','spoon','spatula','badge','bubble','chest'];
 const BOUNDS=[[44,49,190,210],[281,74,205,168],[553,52,179,211],[796,61,189,200],[1058,48,186,224],[1309,50,183,223],[63,281,163,231],[298,302,174,210],[541,309,191,199],[772,333,215,172],[1037,303,236,204],[1305,302,193,210],[36,533,222,217],[295,540,183,203],[536,539,201,189],[783,531,171,228],[1002,555,254,179],[1289,546,219,192],[32,791,230,175],[297,772,199,196],[526,764,205,205],[781,772,199,192],[1046,783,182,183],[1283,783,218,192]];
 const ROOMS={kitchen:0,words:1,sequence:2,memory:3,rhythm:4},NOTES=['도','레','미','솔'];
 let menuBand=null,menuAge=null,menuSet='learning';
 let bridge,active=null,resultRecord=null,currentRoute='',data={drafts:{},discoveryDrafts:{},records:[],muted:false},timers=[],epoch=0,audio=null,lastTick=0,focused=true,saveWarned=false,drag=null,gesture=null,suppressClick=0,suppressNode=null,fxFrame=0,fxParticles=[],ambientTimer=0;
 const F=root.SiaGameHost,L=root.SiaLearning,D=root.SiaDiscover,classicGames=C.GAMES,allGames=[...F.games,...classicGames],archivedGames=[['post-office','숲속 우체국','✉️'],['number-bakery','도토리 빵집','🥐'],['water-lab','둥실 물 연구소','💧'],['seed-garden','씨앗의 작은 정원','🌱']].map(([id,title,icon])=>({id,title,icon}));
 const meta=id=>allGames.concat(archivedGames).find(g=>g.id===id),word=id=>C.WORDS.find(w=>w.id===id),fruit=id=>C.FRUITS.find(f=>f.id===id),draftKey=g=>[g.lang,g.gameId,g.band||'K',g.tier,g.age].join(':');
 const reduce=()=>root.matchMedia('(prefers-reduced-motion: reduce)').matches;
 function sprite(id,classes="",label=""){const i=Math.max(0,PROPS.indexOf(id)),[x,y,w,h]=BOUNDS[i],m=Math.max(w,h);return '<span class="play-toy '+classes+'" '+(label?'role="img" aria-label="'+E(label)+'"':'aria-hidden="true"')+'><span class="play-toy-crop" style="width:'+w/m*100+'%;height:'+h/m*100+'%;background-size:'+1536/w*100+'% '+1024/h*100+'%;background-position:'+x/(1536-w)*100+'% '+y/(1024-h)*100+'%"></span></span>';}
 function btn(label,action,classes='',extra=''){return '<button class="play-button '+classes+'" data-play-action="'+action+'" '+extra+'>'+label+'</button>';}
 function read(){try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved){data.discoveryDrafts=saved.discoveryDrafts&&typeof saved.discoveryDrafts==='object'?saved.discoveryDrafts:{};data.drafts=saved.drafts&&typeof saved.drafts==='object'?saved.drafts:{};data.records=Array.isArray(saved.records)?saved.records.filter(r=>r&&(F.has(r.gameId)?root.SiaGameBridge.validRecord(r):meta(r.gameId)&&r.completedAt)).slice(-40):[];data.muted=Boolean(saved.muted);}}catch{}}
 function save(){try{localStorage.setItem(KEY,JSON.stringify(data));return true;}catch{if(!saveWarned){bridge.toast('놀이 기록을 저장하지 못했어요. 놀이는 계속할 수 있어요.');saveWarned=true;}return false;}}
 function persist(){if(active&&active.phase!=='complete')data.drafts[draftKey(active)]=active;save();}
 function flush(){const now=Date.now(),delta=now-lastTick;if(active&&active.phase!=='complete'&&lastTick&&delta>0&&delta<15000&&!document.hidden&&focused)active.activeMs+=delta;lastTick=now;}
 function stopAsync(){epoch++;timers.forEach(clearTimeout);timers=[];document.querySelectorAll('.play-pad.is-lit').forEach(n=>n.classList.remove('is-lit'));clearInterval(ambientTimer);ambientTimer=0;}
 function later(callback,ms){const generation=epoch;timers.push(setTimeout(()=>{if(generation===epoch&&currentRoute==='play')callback();},ms));}
 function cancelDrag(){drag?.ghost?.remove();drag=null;gesture=null;document.querySelectorAll('.is-drop-target').forEach(n=>n.classList.remove('is-drop-target'));}
 function suspend(){flush();focused=false;stopAsync();cancelDrag();if(active){C.resume(active);persist();if(currentRoute==='play')paintGame();}cancelAnimationFrame(fxFrame);fxParticles=[];}
 function init(api){bridge=api;read();document.addEventListener('click',click);document.addEventListener('keydown',keydown);document.addEventListener('pointerdown',pointerDown);document.addEventListener('pointermove',pointerMove,{passive:false});document.addEventListener('pointerup',pointerUp);document.addEventListener('pointercancel',()=>{suppressClick=Date.now()+300;cancelDrag();});
  F.init({onClose:()=>{paintMenu();$('[data-play-start="fossil-dig"]')?.focus();},onResult:record=>{const existing=data.records.findIndex(r=>r.id===record.id);if(existing>=0)data.records[existing]=record;else data.records.push(record);data.records=data.records.slice(-40);return save();}});
  D?.init({...api,getMuted:()=>data.muted,setMuted:value=>{data.muted=value;save();},getDraft:key=>data.discoveryDrafts[key],onDraft:(key,value)=>{if(value)data.discoveryDrafts[key]=value;else delete data.discoveryDrafts[key];return save();},onClose:id=>{paintMenu();$('[data-play-start="'+id+'"]')?.focus();},onResult:record=>{const i=data.records.findIndex(r=>r.id===record.id);if(i>=0)data.records[i]=record;else data.records.push(record);data.records=data.records.slice(-40);return save();}});
  document.addEventListener('visibilitychange',()=>{if(document.hidden)suspend();else{focused=true;lastTick=Date.now();}});root.addEventListener('blur',suspend);root.addEventListener('focus',()=>{focused=true;lastTick=Date.now();});root.addEventListener('pagehide',()=>{flush();persist();stopAsync();});
  setInterval(()=>{flush();if(active&&active.phase!=='complete')persist();},5000);
 }
 function view(){return '<section id="play-room" class="play-room" aria-label="하루 놀이섬"></section>';}
 function mount(route){currentRoute=route;if(D?.isOpen())D.close();if(F.isOpen())F.close();if(route!=='play'){if(active){flush();C.resume(active);persist();active=null;}stopAsync();cancelDrag();clearFX();return;}if(!$('#play-room'))return;if(active)paintGame();else{paintMenu();const q=new URLSearchParams(location.search),id=q.get('adventure');if(F.meta(id)?.astra){q.delete('adventure');history.replaceState(null,'',location.pathname+(q.size?'?'+q:'')+'#play');start(id);}}}
 function soundButton(){return btn(bridge.icon(data.muted?'close':'volume'),'mute','play-circle', 'aria-label="'+(data.muted?'소리 켜기':'소리 끄기')+'" aria-pressed="'+!data.muted+'"');}
 function canvas(){return '<canvas class="play-fx" aria-hidden="true"></canvas>';}
 function paintMenu(){
  stopAsync();clearFX();resultRecord=null;const p=bridge.getProfile(),lang=p.lang==='en'?'en':'ko',shown=(menuSet==='classic'&&Number(p.age)<=7?classicGames:['star-mail','cloud-bridge','prism-lab','living-forest','letter-flight','fruit-orchard','float-lab','nature-explorer','fossil-dig','fruit-stand'].map(F.meta)).filter(g=>L.core.available(p,g.id,lang)),pending=[...data.records].reverse().find(r=>r.learning&&!r.learning.feedback),completed=new Set(data.records.filter(r=>r.lang===lang&&shown.some(g=>g.id===r.gameId)).map(r=>r.gameId)).size;
  menuBand=L.core.bandFor(p,'play');
  $('#play-room').innerHTML='<section class="play-world"><div class="play-island-art" aria-hidden="true"></div><header class="play-world-header"><a class="play-circle" href="#home" aria-label="처음으로">'+bridge.icon('back')+'</a><div class="play-world-brand"><span>MY SIA · '+p.age+'살</span><h1>'+ (menuSet==='learning'?'하루의 배움 모험':'하루의 놀이섬') +'</h1></div><div class="play-world-tools"><div class="play-language"><button data-lang="ko" class="'+(lang==='ko'?'selected':'')+'" aria-pressed="'+(lang==='ko')+'">한글</button><button data-lang="en" class="'+(lang==='en'?'selected':'')+'" aria-pressed="'+(lang==='en')+'">EN</button></div>'+soundButton()+'</div></header><div class="play-catalog-controls">'+L.bandChip('fossil-dig')+'</div><div class="play-map" aria-label="놀이 고르기">'+shown.map((g,i)=>{
   const n=L.level(g.id,lang),saved=D?.has(g.id)?data.discoveryDrafts[[lang,g.id,n,p.age,menuBand,p.name||''].join(':')]:(data.drafts[[lang,g.id,L.core.bandOf(p,g.id,lang),n,p.age].join(':')]||data.drafts[lang+':'+g.id]),done=data.records.some(r=>r.gameId===g.id&&r.lang===lang);
   return '<div class="play-place"><button class="play-destination destination-'+g.id+(g.astra?' destination-astra':'')+'" data-play-start="'+g.id+'" style="--destination:'+i+'"><span class="play-destination-glow"></span>'+(D?.has(g.id)?'<span class="discover-subject">'+(lang==='en'?g.subjectEn:g.subject)+'</span>'+D.sprite(g.hero,'discover-card-hero'):'')+(F.has(g.id)?(g.astra?'<img class="astra-card-image" src="games/astra/posters/'+g.id+'.png?v='+root.SIA_GAMES_RELEASE?.games?.[g.id]?.sha256?.slice(0,16)+'" alt="" loading="lazy">':'<span class="game-destination-icon" aria-hidden="true">'+g.icon+'</span>'):'')+'<span class="play-destination-label">'+(done?'<span class="play-done-mark" aria-label="완료">✓</span>':'')+'<strong>'+(lang==='en'&&g.en?g.en:g.title)+'</strong><span class="play-destination-arrow" aria-hidden="true">▶</span></span>'+((D?.has(g.id)?root.SiaDiscoveryCore.valid(saved):C.valid(saved))&&saved.tier===n&&(!saved.age||saved.age===p.age)?'<small>이어 하기</small>':'')+'</button><span class="play-level-select play-level-readonly">'+E(L.bandText(g.id,lang))+' · 레벨 '+n+'</span></div>';
  }).join('')+'<div class="play-world-haru"><div class="play-haru-actor"><img src="assets/happy.png" alt="하루"></div><span>어디로 가 볼까?</span></div></div><footer class="play-world-footer"><div class="play-passport">'+sprite('badge')+'<span>함께 발견한 놀이 <b>'+completed+' / '+shown.length+'</b></span></div>'+(classicGames.some(g=>L.core.available(p,g.id,lang))?'<button class="play-collection-toggle" data-play-collection="'+(menuSet==='learning'?'classic':'learning')+'">'+(menuSet==='learning'?'5–7살 놀이 더 보기 →':'배움 모험 10개 →')+'</button>':'')+'</footer>'+(pending?'<button class="play-pending-feedback" data-play-reflect="'+E(pending.id)+'">지난 놀이, 어땠어?</button>':'')+canvas()+'</section>';
 }
 function start(id,fresh=false){if(!meta(id))return;const p=bridge.getProfile(),lang=p.lang==='en'?'en':'ko';if(!L.core.available(p,id,lang))return;menuBand=L.core.bandOf(p,id,lang);const n=L.level(id,lang),key=[lang,id,menuBand,n,p.age].join(':');stopAsync();clearFX();cancelDrag();resultRecord=null;if(D?.has(id)){if(active){flush();C.resume(active);persist();active=null;}D.open($('#play-room'),{...p,gameId:id,playLevel:n,playBand:menuBand},fresh);return;}if(F.has(id)){if(active){flush();C.resume(active);persist();active=null;}F.open($('#play-room'),{...p,gameId:id,playLevel:n,playBand:menuBand});return;}const saved=data.drafts[key]||data.drafts[lang+':'+id];active=!fresh&&C.valid(saved)&&saved.tier===n&&(!saved.age||saved.age===p.age)?C.resume(saved):C.create(id,{...p,playLevel:n,playBand:menuBand},Date.now()+'-'+Math.random().toString(36).slice(2,8));active.age??=p.age;active.band??=menuBand;active.learning??=L.start(id,active.id,{lang:active.lang,band:active.band,level:active.tier});focused=true;lastTick=Date.now();persist();root.scrollTo({top:0});getAudio();paintGame(true);popSound();autoGuide();}
 function scene(page,label){const atlas=root.SIA_STORY_ART?.['K-ko-001']?.episodes?.[1]?.scenes,frame=atlas?.frames.find(f=>f.page===page);if(!frame)return '';const img=frame.image||atlas,cols=frame.image?1:atlas.columns,rows=frame.image?1:atlas.rows,x=frame.image?0:frame.index%cols,y=frame.image?0:Math.floor(frame.index/cols);return '<span class="story-illustration story-page-scene play-scene" style="--scene-columns:'+cols+';--scene-rows:'+rows+';--scene-x:'+x+';--scene-y:'+y+'"><img src="'+E(img.src)+'?v='+E(img.version)+'" width="'+img.width+'" height="'+img.height+'" alt="'+E(label)+'" draggable="false"></span>';}
 function instructions(){const g=active;if(g.phase==='won')return g.gameId==='kitchen'?'냠냠! 정말 맛있어!':'우와, 해냈어!';
  if(g.gameId==='kitchen'){if(g.phase==='prepare')return {slice:'슥슥! 과일을 잘라 줘.',mix:'빙글빙글, 함께 섞어 볼까?',serve:'하루에게 먹여 줘!'}[g.prep.stage];const t=g.tasks[g.round];return fruit(t.fruit).ko+' '+(t.part?t.part+'개와 '+(t.count-t.part)+'개':t.count+'개')+'를 담아 줘!';}
  if(g.gameId==='words')return '소리를 듣고 글자를 이어 줘.';
  if(g.gameId==='sequence')return g.phase==='preview'?'우리 이야기 속으로 가 볼까?':'먼저 일어난 일부터 놓아 줘.';
  if(g.gameId==='memory')return '숨어 있는 동물 짝꿍을 찾아 줘.';
  return g.phase==='showing'?'내 연주를 잘 들어 봐.':g.phase==='repeat'?'이제 네 차례야!':'우리 같이 연주해 볼까?';
 }
 function backdrop(index){return '<div class="play-room-art room-'+index+'" aria-hidden="true"></div><div class="play-room-light" aria-hidden="true"></div>';}
 function guide(){const g=active,m=meta(g.gameId),won=g.phase==='won',reaction=won?'congratulations.png':g.gameId==='rhythm'&&g.phase==='showing'?'happy.png':m.haru;
  return '<aside class="play-companion '+(won?'is-celebrating':'')+'"><div class="play-haru-actor"><img src="assets/'+reaction+'" alt="하루"></div><div class="play-speech"><h1 id="play-title" tabindex="-1">'+instructions()+'</h1>'+btn(bridge.icon('volume'),'guide','play-guide-sound','aria-label="놀이 방법 듣기"')+'</div></aside>';
 }
 function progress(){const g=active;return '<div class="play-rounds" aria-label="'+(g.round+1)+' / '+g.total+'">'+Array.from({length:g.total},(_,i)=>'<span class="'+(i<g.round||i===g.round&&g.phase==='won'?'done':i===g.round?'current':'')+'">'+(i<g.round||i===g.round&&g.phase==='won'?sprite('star'):i+1)+'</span>').join('')+'</div>';}
 function kitchenSteps(){const g=active,index=g.phase==='won'?4:g.phase==='prepare'?{slice:1,mix:2,serve:3}[g.prep.stage]:0;return '<div class="play-cook-steps" aria-label="요리 순서">'+['담기','자르기','섞기','냠냠'].map((v,i)=>'<span class="'+(i<index?'done':i===index?'current':'')+'"><i>'+(i<index?'✓':i+1)+'</i>'+v+'</span>').join('')+'</div>';}
 function bowl(interactive=false){const g=active;return '<div class="play-bowl '+(g.phase==='prepare'?'is-preparing':'')+'" '+(interactive?'data-play-drop="kitchen"':'')+'>'+sprite('bowl','play-bowl-prop')+'<div class="play-bowl-fruits">'+g.bowl.map((id,i)=>'<'+(interactive?'button':'span')+' data-play-remove-fruit="'+i+'" aria-label="'+fruit(id).ko+(interactive?' 빼기':'')+'" style="--fruit-i:'+i+';--fruit-count:'+g.bowl.length+'" '+(g.phase!=='play'?'disabled':'')+'>'+sprite(id)+'</'+(interactive?'button':'span')+'>').join('')+'</div>'+(interactive?'<span class="play-bowl-count" aria-live="polite">'+g.bowl.length+'<small>개</small></span>':'')+'</div>';}
 function kitchen(){
  const g=active,t=g.tasks[g.round],f=fruit(t.fruit);let content='';
  if(g.phase==='play')content='<div class="play-order-ticket">'+sprite(t.fruit)+'<strong>'+(t.part?t.part+' + '+(t.count-t.part):t.count)+'<small>개</small></strong></div><div class="play-prep-counter">'+bowl(true)+'<div class="play-food-bank">'+C.FRUITS.map(f=>'<button class="play-food" data-play-ingredient="'+f.id+'" data-play-focus="fruit-'+f.id+'" aria-label="'+f.ko+' 담기">'+sprite(f.id)+'<b>'+f.ko+'</b></button>').join('')+'</div></div><p class="play-helper">과일을 그릇으로 끌어 담아 줘.</p>';
  else if(g.phase==='prepare'&&g.prep.stage==='slice')content='<div class="play-slicing-board"><button class="play-cut-target" data-play-action="cut" aria-label="과일 자르기"><span class="play-cut-fruit '+(g.prep.cuts?'is-cut':'')+'" style="--cut-count:'+g.prep.cuts+'"><span class="play-fruit-half half-left">'+sprite(t.fruit)+'</span><span class="play-fruit-half half-right">'+sprite(t.fruit)+'</span></span><span class="play-cut-guide" aria-hidden="true"></span></button>'+sprite('spatula','play-spatula')+'<div class="play-cut-marks" aria-label="'+g.prep.cuts+' / 3 번 자르기">'+[0,1,2].map(i=>'<span class="'+(i<g.prep.cuts?'done':'')+'">'+(i<g.prep.cuts?'✓':'·')+'</span>').join('')+'</div></div><p class="play-helper">손가락으로 슥! 눌러서 잘라도 좋아.</p>';
  else if(g.phase==='prepare'&&g.prep.stage==='mix')content='<div class="play-mix-area"><button class="play-mix-target" data-play-action="stir" aria-label="과일 섞기" style="--mix-progress:'+g.prep.mix+'">'+bowl()+sprite('spoon','play-mixing-spoon')+'<span class="play-stir-orbit" aria-hidden="true">↻</span></button><div class="play-mix-meter" role="progressbar" aria-label="섞은 정도" aria-valuemin="0" aria-valuemax="100" aria-valuenow="'+Math.round(g.prep.mix*100)+'"><span style="width:'+g.prep.mix*100+'%"></span></div></div><p class="play-helper">그릇 안에서 동그라미를 그려 줘.</p>';
  else content='<div class="play-serving '+(g.phase==='won'?'is-served':'')+'"><img class="play-hungry-haru" src="assets/'+(g.phase==='won'?'congratulations.png':'happy.png')+'" alt="요리를 기다리는 하루"><button class="play-serve-dish" data-play-action="serve" aria-label="하루에게 먹여 주기" '+(g.phase==='won'?'disabled':'')+'>'+bowl()+'</button>'+(g.phase==='won'?'<span class="play-taste">맛있다!</span>':'<span class="play-serve-label">톡! 먹여 주기</span>')+'</div>';
  return '<div class="play-kitchen">'+kitchenSteps()+content+'</div>';
 }
 function words(){const g=active,t=g.tasks[g.round],w=word(t.wordId);return '<div class="play-word-machine '+(g.phase==='won'?'is-launched':'')+'"><div class="play-word-display">'+sprite(w.id,'play-word-object',w[g.lang])+'<div class="play-object-halo" aria-hidden="true"></div>'+btn(bridge.icon('volume'),'word-speak','play-listen','aria-label="낱말 소리 듣기"')+'</div><div class="play-word-slots" data-play-drop="words" role="group" aria-label="만든 낱말">'+[...t.text].map((_,i)=>{const tile=t.tiles.find(t=>t.id===g.chosen[i]);return '<button class="play-letter-slot '+(tile?'filled':'')+'" data-play-remove="'+i+'" aria-label="'+(tile?E(tile.text)+' 빼기':(i+1)+'번째 자리')+'" '+(!tile||g.phase!=='play'?'disabled':'')+'>'+(tile?E(tile.text):'<span aria-hidden="true">·</span>')+'</button>';}).join('')+'</div><div class="play-letter-bank" aria-label="글자 조각">'+t.tiles.map((tile,i)=>'<button class="play-letter '+(g.chosen.includes(tile.id)?'used':'')+'" data-play-piece="'+tile.id+'" data-play-focus="piece-'+tile.id+'" style="--tile-color:'+(i%4)+';--delay:'+i*45+'ms" aria-label="'+E(tile.text)+' 넣기" '+(g.chosen.includes(tile.id)||g.phase!=='play'?'disabled':'')+'>'+E(tile.text)+'</button>').join('')+'</div></div>';}
 function sequence(){const g=active;
  if(g.phase==='preview'){const card=g.cards[g.preview];return '<div class="play-story-theater"><div class="play-film-screen">'+scene(card.page,card[g.lang])+'<span class="play-film-count">'+(g.preview+1)+' / '+g.cards.length+'</span></div><div class="play-story-caption"><p lang="'+g.lang+'">'+E(card[g.lang])+'</p>'+btn(bridge.icon('volume'),'scene-speak','play-circle','aria-label="장면 듣기"')+'</div><div class="play-preview-controls">'+btn(g.preview+1===g.cards.length?'순서 맞추기 '+bridge.icon('arrow'):'다음 장면 '+bridge.icon('arrow'),'preview-next','play-primary')+'</div></div>';}
  return '<div class="play-story-puzzle"><div class="play-story-slots" data-play-drop="sequence" style="--card-count:'+g.cards.length+'" aria-label="이야기 순서">'+g.cards.map((_,i)=>{const card=g.cards.find(c=>c.page===g.chosen[i]);return '<button class="play-story-slot '+(card?'filled':'')+'" data-play-remove="'+i+'" aria-label="'+(i+1)+'번째 '+(card?E(card[g.lang])+' 빼기':'빈자리')+'" '+(!card||g.phase!=='play'?'disabled':'')+'><span class="play-slot-number">'+(i+1)+'</span>'+(card?scene(card.page,card[g.lang]):'<span class="play-slot-empty">'+(i===0?'처음':i===g.cards.length-1?'마지막':'그다음')+'</span>')+'</button>';}).join('')+'</div><div class="play-story-bank" style="--card-count:'+g.cards.length+'">'+g.order.map(page=>{const card=g.cards.find(c=>c.page===page);return '<button class="play-story-piece '+(g.chosen.includes(page)?'used':'')+'" data-play-piece="'+page+'" data-play-focus="piece-'+page+'" '+(g.chosen.includes(page)||g.phase!=='play'?'disabled':'')+'>'+scene(page,card[g.lang])+'<span lang="'+g.lang+'">'+E(card[g.lang])+'</span></button>';}).join('')+'</div>'+btn(bridge.icon('book')+' 다시 보기','preview-again','play-small',g.phase==='won'?'disabled':'')+'</div>';
 }
 function memory(){const g=active;return '<div class="play-memory-status" role="status" aria-label="찾은 짝꿍 '+g.matched.length/2+' / '+g.deck.length/2+'"><span>찾은 짝꿍</span>'+Array.from({length:g.deck.length/2},(_,i)=>sprite('star',i<g.matched.length/2?'':'is-empty')).join('')+'</div><div class="play-memory-grid" style="--memory-cols:'+(g.deck.length===6?3:4)+'">'+g.deck.map((card,i)=>{const w=word(card.pair),open=g.flipped.includes(card.id)||g.matched.includes(card.id),matched=g.matched.includes(card.id);return '<button class="play-memory-card '+(open?'revealed':'')+' '+(matched?'matched':'')+'" data-play-card="'+card.id+'" data-play-focus="card-'+card.id+'" aria-label="'+(i+1)+'번 카드'+(open?' '+E(w[g.lang]):'')+(matched?' 짝 찾음':'')+'" '+(matched||g.phase!=='play'?'disabled':'')+'><span class="play-card-inner"><span class="play-card-back" aria-hidden="'+open+'">'+sprite('chest')+'<span>'+(i+1)+'</span></span><span class="play-card-front" aria-hidden="'+!open+'">'+sprite(w.id)+'<b lang="'+g.lang+'">'+E(w[g.lang])+'</b></span></span>'+(matched?'<i aria-hidden="true">✓</i>':'')+'</button>';}).join('')+'</div>';}
 function rhythm(){const g=active,len=C.rhythmSequence(g).length;return '<div class="play-concert"><div class="play-concert-haru '+(g.phase==='showing'?'is-dancing':'')+'"><img src="assets/'+(g.phase==='won'?'congratulations.png':'happy.png')+'" alt="함께 연주하는 하루"><div class="play-sound-rings" aria-hidden="true"></div></div><div class="play-rhythm-progress" aria-label="'+len+'개 순서">'+Array.from({length:len},(_,i)=>'<span class="'+(i<g.input.length?'done':'')+'">'+(i<g.input.length?'✓':i+1)+'</span>').join('')+'</div><div class="play-pads">'+NOTES.map((note,i)=>'<button class="play-pad play-pad-'+i+'" data-play-pad="'+i+'" aria-label="'+(i+1)+'번 '+note+'" '+(g.phase!=='repeat'?'disabled':'')+'><span class="play-pad-face"><b>'+note+'</b><small>'+(i+1)+'</small></span><span class="play-pad-light" aria-hidden="true"></span></button>').join('')+'</div><div class="play-rhythm-controls">'+(['ready','repeat'].includes(g.phase)?btn(bridge.icon('volume')+(g.phase==='repeat'?' 다시 듣기':' 하루 연주 듣기'),'rhythm-demo','play-primary'):g.phase==='showing'?'<span class="play-listening-indicator"><i></i><i></i><i></i>잘 들어 봐!</span>':'')+'</div></div>';}
 function paintGame(focus=false){
  if(!active||!$('#play-room'))return;const g=active,m=meta(g.gameId),restore=document.activeElement?.dataset.playFocus;if(g.phase==='complete'){paintResult();return;}
  const scroll=$('.play-stage')?.scrollTop||0,body=({kitchen,words,sequence,memory,rhythm}[g.gameId])(),won=g.phase==='won',showCheck=['kitchen','words','sequence'].includes(g.gameId)&&g.phase==='play';
  const canCheck=g.gameId==='kitchen'?g.bowl.length>0:g.gameId==='words'?g.chosen.length===g.tasks[g.round].text.length:g.gameId==='sequence'?g.chosen.length===g.cards.length:false;
  const footer=won?btn(g.round+1===g.total?'다 놀았어! '+bridge.icon('check'):'다음 놀이 '+bridge.icon('arrow'),'next','play-primary'):showCheck?btn(g.gameId==='kitchen'?'요리 시작!':g.gameId==='words'?'낱말 완성!':'이야기 완성!','check','play-primary',canCheck?'':'disabled'):'';
  $('#play-room').innerHTML='<section class="play-game game-'+g.gameId+' phase-'+g.phase+(focus?' scene-enter':'')+'" data-play-active="'+m.id+'" role="dialog" aria-modal="true" aria-labelledby="play-title">'+backdrop(ROOMS[g.gameId])+'<header class="play-game-header">'+btn(bridge.icon('back'),'menu','play-circle','aria-label="놀이섬으로"')+'<div class="play-game-heading"><span>'+m.title+' · 레벨 '+g.tier+'</span>'+progress()+'</div>'+soundButton()+'</header><div class="play-game-body">'+guide()+'<div class="play-stage">'+body+'</div></div><div class="play-feedback '+(g.message?'visible':'')+' '+(won?'success':'')+'" role="status" aria-live="polite">'+E(g.message||'')+'</div><footer class="play-game-footer">'+footer+'</footer>'+canvas()+'</section>';
  if($('.play-stage'))$('.play-stage').scrollTop=focus?0:scroll;
  if(focus)$('#play-title')?.focus({preventScroll:true});else if(restore){[...document.querySelectorAll('[data-play-focus]')].find(n=>n.dataset.playFocus===restore&&!n.disabled)?.focus({preventScroll:true});}
  clearFX();if(won)burst(innerWidth*.55,innerHeight*.45,60);
 }
 function paintResult(record){stopAsync();clearFX();const r=record||data.records.find(r=>r.id===active?.id);if(!r)return;resultRecord=r;const m=meta(r.gameId),answered=Boolean(r.learning?.feedback);$('#play-room').innerHTML='<section class="play-result">'+backdrop(5)+'<a href="#home" class="play-circle play-result-home" aria-label="처음으로">'+bridge.icon('back')+'</a><div class="play-result-content"><div class="play-result-stars" aria-label="놀이 완료">'+Array.from({length:L.core.gameStars(r)},(_,i)=>sprite('star','result-star star-'+i)).join('')+'</div><img class="play-result-haru" src="assets/congratulations.png" alt="축하해 주는 하루"><p>'+m.title+' · 레벨 '+(r.learning?.level||r.tier||1)+'</p><h1>우리 같이 해냈어!</h1>'+L.feedbackHtml(r.learning)+'<div class="play-result-actions">'+btn('놀이섬으로','menu','play-primary',answered?'':'disabled')+btn('한 번 더','again','play-secondary',answered?'':'disabled')+'</div></div>'+canvas()+'</section>';if(!answered){burst(innerWidth*.5,innerHeight*.3,60);jingle();}}
 function feedback(message,success=false){active.message=message;paintGame();persist();if(success)jingle();else{popSound(.7);$('.play-stage')?.animate(reduce()?[]:[{transform:'translateX(0)'},{transform:'translateX(-5px)'},{transform:'translateX(5px)'},{transform:'translateX(0)'}],{duration:280});}}
 function addFruit(id){if(!active||active.gameId!=='kitchen'||active.phase!=='play'||!fruit(id))return;if(active.bowl.length>=16){feedback('그릇이 가득 찼네! 과일을 눌러 빼 봐.');return;}active.bowl.push(id);active.message='';paintGame();persist();popSound(1+active.bowl.length*.06);sparkAt('.play-bowl',12);}
 function addPiece(id){if(C.choose(active,id)){active.message='';paintGame();persist();popSound(1.2);sparkAt(active.gameId==='words'?'.play-word-slots':'.play-story-slots',12);}}
 function check(){const correct=C.check(active);if(correct===null)return;if(correct){active.message='';paintGame();persist();jingle();if(active.gameId==='kitchen')autoGuide();if(active.gameId!=='kitchen')burst(innerWidth*.5,innerHeight*.4,55);}else feedback(active.gameId==='kitchen'?'종류와 개수를 다시 볼까?':active.gameId==='words'?'소리를 듣고 다시 이어 봐.':'이야기를 다시 보고 바꿔 봐.');}
 function cut(){if(!C.cut(active))return;paintGame();persist();popSound(.8);sparkAt('.play-cut-target',18);if(active.prep.stage==='mix')autoGuide();}
 function stir(amount=.2){if(!C.stir(active,amount))return;const progress=active.prep.mix;if(active.prep.stage==='serve'){paintGame();jingle();autoGuide();}else{const target=$('.play-mix-target'),meter=$('.play-mix-meter');target?.style.setProperty('--mix-progress',progress);if(meter){meter.setAttribute('aria-valuenow',Math.round(progress*100));meter.firstElementChild.style.width=progress*100+'%';}}persist();}
 function serve(){if(!C.serve(active))return;active.message='하루랑 나눠 먹으니 더 맛있어!';paintGame();persist();jingle();}
 function finishRound(){flush();stopAsync();active.message='';if(!C.advance(active))return;if(active.phase==='complete'){active.learning??=L.start(active.gameId,active.id,{lang:active.lang,band:active.band,level:active.tier});active.learning.completedAt=active.completedAt;if(!data.records.some(r=>r.id===active.id))data.records.push({...C.report(active),stars:L.core.gameStars(C.report(active)),learning:active.learning,age:active.age,band:active.band});data.records=data.records.slice(-40);delete data.drafts[draftKey(active)];if(data.drafts[active.lang+':'+active.gameId]?.id===active.id)delete data.drafts[active.lang+':'+active.gameId];save();}else persist();paintGame(true);if(active.phase!=='complete')autoGuide();}
 function menu(){flush();stopAsync();cancelDrag();if(active)C.resume(active);persist();active=null;root.SiaVoice?.stop();paintMenu();root.scrollTo({top:0});}
 function getAudio(){if(data.muted)return null;try{const Audio=root.AudioContext||root.webkitAudioContext;if(!Audio)return null;audio??=new Audio();if(audio.state==='suspended')audio.resume().catch(()=>{});return audio;}catch{return null;}}
 function note(freq,duration=.35,delay=0,type='sine',level=.12){const ctx=getAudio();if(!ctx)return;const now=ctx.currentTime+delay,osc=ctx.createOscillator(),gain=ctx.createGain();osc.type=type;osc.frequency.setValueAtTime(freq,now);gain.gain.setValueAtTime(.0001,now);gain.gain.exponentialRampToValueAtTime(level,now+.012);gain.gain.exponentialRampToValueAtTime(.0001,now+duration);osc.connect(gain);gain.connect(ctx.destination);osc.start(now);osc.stop(now+duration+.02);osc.onended=()=>{osc.disconnect();gain.disconnect();};}
 function tone(i){const freq=[261.63,293.66,329.63,392][i]||523.25;note(freq,.45,0,'sine',.16);note(freq*2,.25,.008,'sine',.025);}
 function popSound(pitch=1){note(540*pitch,.13,0,'sine',.06);note(850*pitch,.09,.04,'sine',.035);}
 function jingle(){[523.25,659.25,783.99,1046.5].forEach((f,i)=>note(f,.38,i*.08,'sine',.075));}
 function say(text,lang='ko'){if(data.muted){bridge.toast('소리를 켜면 들을 수 있어.');return;}bridge.speak(text,lang==='en'?'en-US':'ko-KR');}
 function showPattern(){if(active?.gameId!=='rhythm'||!['ready','repeat'].includes(active.phase))return;getAudio();stopAsync();root.SiaVoice?.stop();active.phase='showing';active.input=[];active.message='';paintGame();persist();const seq=C.rhythmSequence(active);
  seq.forEach((pad,i)=>{later(()=>{const el=$('[data-play-pad="'+pad+'"]');el?.classList.add('is-lit');tone(pad);sparkAt('[data-play-pad="'+pad+'"]',8);},300+i*760);later(()=>$('[data-play-pad="'+pad+'"]')?.classList.remove('is-lit'),820+i*760);});
  later(()=>{active.phase='repeat';paintGame();persist();},seq.length*760+400);
 }
 function updateMemory(){
  if(active.phase==='won'){paintGame();return;}
  const g=active;
  for(let i=0;i<g.deck.length;i++){const card=g.deck[i],node=$('[data-play-card="'+card.id+'"]');if(!node)continue;const open=g.flipped.includes(card.id)||g.matched.includes(card.id),matched=g.matched.includes(card.id);node.classList.toggle('revealed',open);node.classList.toggle('matched',matched);node.querySelector('.play-card-front')?.setAttribute('aria-hidden',String(!open));node.querySelector('.play-card-back')?.setAttribute('aria-hidden',String(open));node.disabled=matched;node.setAttribute('aria-label',(i+1)+'번 카드'+(open?' '+word(card.pair)[g.lang]:'')+(matched?' 짝 찾음':''));if(matched&&!node.querySelector('i'))node.insertAdjacentHTML('beforeend','<i aria-hidden="true">✓</i>');}
  $('.play-memory-status')?.setAttribute('aria-label','찾은 짝꿍 '+g.matched.length/2+' / '+g.deck.length/2);document.querySelectorAll('.play-memory-status .play-toy').forEach((el,i)=>el.classList.toggle('is-empty',i>=g.matched.length/2));
  const message=$('.play-feedback');if(message){message.textContent=g.message||'';message.classList.toggle('visible',Boolean(g.message));}
 }
 function flip(id){const result=C.flip(active,id);if(!result)return;const card=active.deck.find(c=>c.id===id);say(word(card.pair)[active.lang],active.lang);active.message=result==='match'?'짝꿍을 찾았네!':result==='complete'?'모든 짝꿍을 찾았어!':'';updateMemory();persist();popSound();if(result==='miss')later(()=>{active.flipped=[];active.message='';updateMemory();persist();},1300);if(result==='complete')jingle();if(result==='match')sparkAt('[data-play-card="'+id+'"]',26);}
 function autoGuide(){if(data.muted)return;later(()=>{if(!active)return;if(active.gameId==='words'&&active.phase==='play')say(active.tasks[active.round].text,active.lang);else say(instructions());},350);}
 function click(event){if(currentRoute!=='play')return;const action=event.target.closest('[data-play-action]')?.dataset.playAction;
  const collection=event.target.closest('[data-play-collection]');if(collection){menuSet=collection.dataset.playCollection;paintMenu();return;}
  if(action==='mute'){data.muted=!data.muted;if(data.muted)root.SiaVoice?.stop();save();if(active)paintGame();else paintMenu();return;}
  const reflect=event.target.closest('[data-play-reflect]');if(reflect){const record=data.records.find(r=>r.id===reflect.dataset.playReflect);if(record){if(D?.has(record.gameId))D.review($('#play-room'),record);else paintResult(record);}return;}
  const feeling=event.target.closest('[data-learning-feedback]');if(feeling&&resultRecord){if(L.respond(resultRecord.learning,feeling.dataset.learningFeedback,L.core.gameScore(resultRecord))){save();paintResult(resultRecord);}return;}
  if(resultRecord&&action==='menu'){menu();return;}if(resultRecord&&action==='again'){start(resultRecord.gameId,true);return;}
  const startButton=event.target.closest('[data-play-start]');if(startButton){start(startButton.dataset.playStart);return;}if(!active)return;focused=true;
  if(Date.now()<suppressClick&&suppressNode?.contains(event.target))return;
  const ingredient=event.target.closest('[data-play-ingredient]'),piece=event.target.closest('[data-play-piece]');if(ingredient||piece){if(ingredient)addFruit(ingredient.dataset.playIngredient);else addPiece(Number(piece.dataset.playPiece));return;}
  const remove=event.target.closest('[data-play-remove]');if(remove&&active.phase==='play'){active.chosen.splice(Number(remove.dataset.playRemove),1);active.message='';paintGame();persist();popSound(.8);return;}
  const removeFruit=event.target.closest('[data-play-remove-fruit]');if(removeFruit&&active.phase==='play'){active.bowl.splice(Number(removeFruit.dataset.playRemoveFruit),1);active.message='';paintGame();persist();return;}
  const card=event.target.closest('[data-play-card]');if(card){flip(card.dataset.playCard);return;}
  const pad=event.target.closest('[data-play-pad]');if(pad){const n=Number(pad.dataset.playPad),result=C.tap(active,n);if(!result)return;tone(n);if(result==='miss')feedback('한 번 더 듣고 해 보자.');else if(result==='complete')feedback('멋진 연주였어!',true);else{paintGame();$('[data-play-pad="'+n+'"]')?.classList.add('is-lit');sparkAt('[data-play-pad="'+n+'"]',10);later(()=>$('[data-play-pad="'+n+'"]')?.classList.remove('is-lit'),200);persist();}return;}
  if(!action)return;if(action==='menu')menu();else if(action==='again')start(active.gameId,true);else if(action==='check')check();else if(action==='next')finishRound();else if(action==='word-speak')say(active.tasks[active.round].text,active.lang);else if(action==='scene-speak')say(active.cards[active.preview][active.lang],active.lang);
  else if(action==='guide')say(instructions());else if(action==='cut')cut();else if(action==='stir'){stir(.2);popSound(.7);}else if(action==='serve')serve();
  else if(action==='preview-next'){if(active.preview+1<active.cards.length)active.preview++;else active.phase='play';active.message='';paintGame(true);persist();popSound();}
  else if(action==='preview-again'){active.phase='preview';active.preview=0;active.message='';paintGame(true);persist();}else if(action==='rhythm-demo')showPattern();
 }
 function keydown(event){if(currentRoute!=='play'||!active||active.phase==='complete')return;if(event.key==='Escape'){event.preventDefault();menu();return;}if(event.key!=='Tab')return;const nodes=[...document.querySelectorAll('.play-game button:not(:disabled),.play-game a[href]')],first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&(document.activeElement===first||document.activeElement?.id==='play-title')){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}
 function pointerDown(event){if(currentRoute!=='play'||!active||event.button!==0)return;
  if(active.phase==='prepare'){const target=event.target.closest('.play-cut-target,.play-mix-target');if(target){const rect=target.getBoundingClientRect();gesture={source:target,id:event.pointerId,x:event.clientX,y:event.clientY,cx:rect.x+rect.width/2,cy:rect.y+rect.height/2,angle:Math.atan2(event.clientY-rect.y-rect.height/2,event.clientX-rect.x-rect.width/2),distance:0,stage:active.prep.stage};target.setPointerCapture(event.pointerId);}return;}
  if(active.phase!=='play')return;const source=event.target.closest('[data-play-ingredient],[data-play-piece]');if(!source||source.disabled)return;drag={source,id:event.pointerId,x:event.clientX,y:event.clientY,moved:false,ghost:null,gameId:active.id};source.setPointerCapture(event.pointerId);
 }
 function pointerMove(event){
  if(gesture&&gesture.id===event.pointerId){event.preventDefault();const g=gesture;if(active?.phase!=='prepare')return;
   if(g.stage==='slice'){g.distance+=Math.hypot(event.clientX-g.x,event.clientY-g.y);g.x=event.clientX;g.y=event.clientY;if(g.distance>70){suppressClick=Date.now()+500;suppressNode=g.source;gesture=null;cut();}}
   else if(g.stage==='mix'){const angle=Math.atan2(event.clientY-g.cy,event.clientX-g.cx);let delta=angle-g.angle;if(delta>Math.PI)delta-=Math.PI*2;if(delta< -Math.PI)delta+=Math.PI*2;g.angle=angle;if(Math.hypot(event.clientX-g.cx,event.clientY-g.cy)>25&&Math.abs(delta)<1){g.distance+=Math.abs(delta);stir(Math.abs(delta)/(Math.PI*6));if(g.distance>.15){suppressClick=Date.now()+400;suppressNode=g.source;}}}
   return;
  }
  if(!drag||event.pointerId!==drag.id)return;const d=drag;if(!d.moved&&Math.hypot(event.clientX-d.x,event.clientY-d.y)>8){d.moved=true;d.ghost=d.source.cloneNode(true);d.ghost.className='play-drag-ghost';d.ghost.setAttribute('aria-hidden','true');d.ghost.removeAttribute('id');document.body.appendChild(d.ghost);}
  if(d.moved){event.preventDefault();d.ghost.style.left=(event.clientX-45)+'px';d.ghost.style.top=(event.clientY-45)+'px';const target=document.elementFromPoint(event.clientX,event.clientY)?.closest('[data-play-drop]');document.querySelectorAll('[data-play-drop]').forEach(n=>n.classList.toggle('is-drop-target',n===target));}
 }
 function pointerUp(event){if(gesture&&gesture.id===event.pointerId){gesture=null;return;}if(!drag||event.pointerId!==drag.id)return;const d=drag;if(d.moved){suppressClick=Date.now()+400;suppressNode=d.source;const target=document.elementFromPoint(event.clientX,event.clientY)?.closest('[data-play-drop]');if(target&&active?.id===d.gameId&&target.dataset.playDrop===active.gameId){if(d.source.dataset.playIngredient)addFruit(d.source.dataset.playIngredient);else addPiece(Number(d.source.dataset.playPiece));}}cancelDrag();}
 function clearFX(){cancelAnimationFrame(fxFrame);fxFrame=0;fxParticles=[];}
 function sparkAt(selector,count){const rect=$(selector)?.getBoundingClientRect();if(rect)burst(rect.x+rect.width/2,rect.y+rect.height/2,count);}
 function burst(x,y,count=30){if(reduce()||document.hidden)return;const colors=['#fff09a','#fff','#65edda','#ff917b','#a496ff'];for(let i=0;i<count;i++)fxParticles.push({x,y,vx:(Math.random()-.5)*9,vy:-Math.random()*8-1,life:1,size:3+Math.random()*5,angle:Math.random()*6,color:colors[i%colors.length]});if(!fxFrame)drawFX();}
 function drawFX(){const el=$('.play-fx');if(!el){clearFX();return;}const dpr=Math.min(root.devicePixelRatio||1,2),w=innerWidth,h=innerHeight;if(el.width!==w*dpr||el.height!==h*dpr){el.width=w*dpr;el.height=h*dpr;}const ctx=el.getContext('2d');if(!ctx)return;ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);for(const p of fxParticles){p.x+=p.vx;p.y+=p.vy;p.vy+=.13;p.life-=.017;p.angle+=.07;ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.angle);ctx.globalAlpha=Math.max(0,p.life);ctx.fillStyle=p.color;ctx.fillRect(-p.size/2,-p.size/2,p.size,p.size*.6);ctx.restore();}fxParticles=fxParticles.filter(p=>p.life>0);fxFrame=fxParticles.length?requestAnimationFrame(drawFX):0;}
 function parentSummary(){const rows=data.records.slice(-8).reverse();return '<section class="play-parent-card"><h2>놀이에서 자라는 힘</h2><div class="play-skill-list">'+allGames.map(g=>'<span><b>'+g.icon+' '+g.title+'</b>'+g.skill+'</span>').join('')+'</div>'+(rows.length?'<div class="play-records">'+rows.map(r=>{const g=meta(r.gameId),date=new Date(r.completedAt).toLocaleDateString('ko-KR'),lang=r.lang==='en'?'영어':'한글';if(D?.has(r.gameId))return D.parentRecord(r);if(F.has(r.gameId))return F.parentRecord(r);return '<div><span aria-hidden="true">'+g.icon+'</span><div><strong>'+g.title+'</strong><small>'+date+' · '+lang+' · 단계 '+r.tier+'</small></div><p>'+r.rounds+'판 완료<br><small>다시 도전 '+(r.retries||0)+'번</small></p></div>';}).join('')+'</div>':'<p class="play-parent-empty">놀이를 마치면 이곳에 기록이 남아요.</p>')+'<a href="#play" class="btn outline">하루 놀이섬 열기 '+bridge.icon('arrow')+'</a></section>';}
 function exportData(){D?.persist();flush();persist();return JSON.parse(JSON.stringify(data));}
 root.SiaPlay={init,view,mount,parentSummary,exportData};
})(window);
